import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import Insignia from '../../common/Insignia';
import Emblem from '../../common/Emblem';
import { levelLabel, tierName } from '../../common/names';
/** An avatar for a plain row: core's Avatar wants a user model. */
export const avatarUser = row => ({
  avatarUrl: () => row.avatarUrl,
  displayName: () => row.displayName,
  username: () => row.username,
  color: () => row.color || ''
});
export const memberUrl = row => app.route('user.renown', {
  username: row.slug
});
export function MemberCell(row) {
  return m(Link, {
    className: "RenownMember",
    href: memberUrl(row)
  }, m(Avatar, {
    user: avatarUser(row),
    className: "RenownMember-avatar"
  }), m("span", {
    className: "RenownMember-name"
  }, row.displayName));
}
export function Standing(row) {
  return m("span", {
    className: "RenownStanding"
  }, m(Insignia, {
    level: row.level,
    size: 20,
    decorative: true
  }), row.prestige > 0 ? m(Emblem, {
    tier: row.prestige,
    size: 20,
    decorative: true
  }) : null, m("span", {
    className: "RenownStanding-text"
  }, levelLabel(row.level), row.prestige > 0 ? m("span", {
    className: "RenownStanding-tier"
  }, " \xB7 ", tierName(row.prestige)) : null));
}
flarum.reg.add('ernestdefoe-renown', 'forum/components/Member', { avatarUser: avatarUser,memberUrl: memberUrl,MemberCell: MemberCell,Standing: Standing, });